// Batch 2a (the hub shell and the Kitchen device's shell half): after-evidence under audits/evidence/p6/2a/ (the finding
// scripts' outputs in p2/ p4/, every script's console output before and after in tests/, the checks in checks/, the
// reviewers' final composites in review/, the kitchen and admin probes in probes/).
const K2 = (id, note, after, status = 'FIXED') => [id, { status, batch: '2a', note, after }];
const S2a = [
  K2("P2-HOME-01", "Home is built once per person and each part is patched in place, so the reminder field is never replaced. verify-reminder-draft-wiped-by-pull-2 (1 char/s over 43 s, WebKit and Chromium): #view-home rebuilt 1× and the field emptied at 28.8 s → rebuilt 0×, no keystroke lost, all 44 characters and focus kept. -1: the draft cut to \"\" with focus on BODY → the whole sentence kept, and a visibilitychange pull keeps it too (was emptied). leads retype: value \"\" → kept, rebuilt 1× → 0×.", ["audits/evidence/p6/2a/tests/repro-after/phase2__HOME__verify-reminder-draft-wiped-by-pull-2.txt","audits/evidence/p6/2a/tests/repro-after/phase2__HOME__verify-reminder-draft-wiped-by-pull-1.txt","audits/evidence/p6/2a/p2/HOME/verify2-reminder-draft.json","audits/evidence/p6/2a/p2/HOME/leads-retype-after.png"]),
  K2("P2-HOME-03", "showPicker() now sets the tab and hash to Home, so whoever signs in next starts on Home by every route (Switch, a 401, the TV's Switch, a guest's expiry). verify-switch-lands-on-me-1: all six cases land on #home after, but they already did on the pre-batch code: batch 0c's Switch handler resets the hash (e9e5f59); the Phase 2 run landed on #me. verify-switch-lands-on-me-2 crashes before and after: once Ezra lands on Home it waits for #switch, which lives on Me (the script, not the app).", ["audits/evidence/p6/2a/tests/repro-after/phase2__HOME__verify-switch-lands-on-me-1.txt","audits/evidence/p6/2a/tests/repro-before/phase2__HOME__verify-switch-lands-on-me-1.txt","audits/evidence/p6/2a/p2/HOME/verify-switch-lands-on-me-1.json","audits/evidence/p6/2a/p2/HOME/leads-switch-kid-lands.png"]),
  K2("P2-PROF-09", "Closed by the Kitchen device (KITCHEN-1 in 0d, KITCHEN-2 here), as P5-D5 decided; no idle timer. test-kitchen 55/0: nobody signs in as a person on the kitchen device (Mea, Eli) and it stays the kitchen; it has no chat, no admin, reads no one's person rows and cannot write F260 or a private prayer list; no other device signs in as the kitchen. smoke-api 275/0 keeps the server half. verify-no-idle-signout-2 was not rerun (not the check, per the entry).", ["audits/evidence/p6/2a/tests/suites/test-kitchen.txt","audits/evidence/p6/2a/tests/smoke-api.txt","audits/evidence/p6/2a/probes/kitchen-probe.json"]),
  K2("P2-PWA-05", "The feed reloads on every pull and when the page becomes visible. verify-feed-not-live-1: Mom's new line never reached the iPad Home in 70 s (0 feed requests) → it shows from the 30 s pull on (2 requests); Eli's own reminder line after the next pull false → true; after Apps → Home false → true. The findings reviewer's check after review round 1: 0 feed replacements per pull in WebKit and Chromium (the Show-more flag no longer rides on feedFresh).", ["audits/evidence/p6/2a/tests/repro-after/phase2__PWA__verify-feed-not-live-1.txt","audits/evidence/p6/2a/p2/PWA/verify-feed-not-live-1.json"]),
  K2("UX-CHAT-01", "For a kid every chat reply is spoken and each bubble has a 64 px speaker that replays it; a kid's speech never carries over to the next person after Switch (security review). The worker's probe with a stand-in speechSynthesis (not filed): four 64 px speakers, a tap spoke \"Your verse is Acts 2:42!\". Real speech of a new, streamed reply was not heard (the rig has no voices, and iOS may hold speech a tap did not start). On the iPad as Ezra, ask Chat a question: the reply should be read aloud by itself, and the speaker beside it should read it again.", ["audits/evidence/p6/2a/tests/smoke-chat.txt"], "NEEDS DEVICE CHECK"),
  K2("UX-HOME-1", "Adult Home on the iPad reads its key numbers at the glance sizes (data-glance, --fs-glance-3/-2), and the Kitchen device's Home is the calm layout (KITCHEN-2). glance.mjs, iPad portrait: next reading, fridge count, prayer count, kids' stars and the timer pill 2.7-3.5 → 6.0 mm (H2 at 2 m), fridge item names 1.7 → 3.1 mm, kid star count 5.2 → 10.4 mm (H1 at 2 m). Still below: the ring label (3.1), the reading sub-line (2.3), reminder text (3.1), bylines (1.7) and the feed (2.7/1.7 mm). No batch is named for the rest.", ["audits/evidence/p6/2a/tests/repro-after/phase2__HOME__glance.txt","audits/evidence/p6/2a/p2/HOME/glance.json","audits/evidence/p6/2a/p2/HOME/glance-adult-ipad-portrait.png","audits/evidence/p6/2a/review/m-k820.png"], "PARTIAL"),
  K2("UX-HOME-8", "Finishing a household reminder hides the row and shows the shared toast with Undo for 6 s; it is removed for everyone only after that (at once if the page hides or someone switches). leads done: the guest's ✓ deleted the row at once with no toast → toast \"Done: … Undo\", the row still stored after the flush; the worker's probe (not filed): Undo brings back 4 rows, gone after 6 s. Review fixes: a pending ✓ belongs to its person and is dropped on a session loss; the kitchen Home uses the same delayed removal (test-kitchen: a guest's reminder survives Undo, no refused write).", ["audits/evidence/p6/2a/p2/HOME/leads-done.json","audits/evidence/p6/2a/p2/HOME/leads-done-after-tap.png","audits/evidence/p6/2a/tests/suites/test-kitchen.txt"]),
  K2("UX-SYNC-a1", "The viewer bar shows the shared sync state over every app: \"Saving…\", \"Offline · N waiting\" (on a phone \"N waiting\", the app name kept, beside a running timer). The screens reviewer's composite shows it over the park map, Tally, F260, the Larder and Prayer; e7-sync-ui's screenshot shows \"3 waiting\" over F260 offline. e7-sync-ui part 3 still prints null before and after because it looks inside F260's frame, not at the shell's bar; its Me-card parts now read \"Up to date\" / \"Saving…\" (were a stale \"pending\").", ["audits/evidence/p6/2a/p2/SYNC/e7-phone-f260-offline-pending.png","audits/evidence/p6/2a/review/m-viewer.png","audits/evidence/p6/2a/tests/repro-after/phase2__SYNC__e7-sync-ui.txt"]),
  K2("GAP-ACCENT-1", "Me → Admin → Edit, Add a person and Add a guest offer the 18 named families: the nine people's colours first, then the nine app colours, each labelled with its app. A live note warns on a colour someone wears, an app's colour and a colour-blind look-alike (cvd-pairs, graphic tone: 16 pairs under ΔE2000 6 for protan/deutan; people's nine never closer than 11 there); the admin decides. The Worker accepts only the 18 names (smoke-api: an unknown family → 400). Review round 1 found colours did not save (the fallback sent a name) → fixed: Edit Mea coral, Add a person leaf, Add a guest orchid all save. test-guests: the sheet shows the 18 families.", ["audits/evidence/p6/2a/probes/admin-390-light-add.png","audits/evidence/p6/2a/probes/cvd-pairs.json","audits/evidence/p6/2a/tests/suites/test-guests.txt","audits/evidence/p6/2a/tests/smoke-api.txt"]),
  K2("GAP-PROF-a2", "Me → Admin → Household: add an adult or a kid (one of the 18 families; an adult gets a one-time set-up code), remove a person, add an admin, take admin away, hand over admin; every change asks for the admin PIN. smoke-api 215 → 275/0: add without or with a wrong PIN 403; a kid or a PIN-less adult cannot be admin; a co-admin's PIN reset needs the PIN; the last admin cannot drop it; hand over and back; self, an admin, the TV and the kitchen cannot be removed; a removed id is never reused. Limitation: a new person sees only the apps open to everyone until apps.json names them.", ["audits/evidence/p6/2a/tests/smoke-api.txt","audits/evidence/p6/2a/probes/admin-390-light-household.png","audits/evidence/p6/2a/probes/admin-390-light-pick.png","audits/evidence/p6/2a/review/m-admin.png"]),
  K2("P2-HOME-05", "Home is built once per person and each part is patched only when its markup changes. verify-home-full-rebuild-every-pull-2, WebKit and Chromium: one pull kept 0/465 nodes and 0/13 images → 476/476 and 13/13; 65 s hands-off 2 → 0 rebuilds; behind an app opened from Home 1 → 0. -1: 2 → 0 rebuilds in 70 s, the per-pull Home share 3 → 1 ms (WebKit), 11 → 5.9 ms task (Chromium). The findings reviewer after round 1: 0 feed replacements per pull in both engines.", ["audits/evidence/p6/2a/tests/repro-after/phase2__HOME__verify-home-full-rebuild-every-pull-2.txt","audits/evidence/p6/2a/tests/repro-after/phase2__HOME__verify-home-full-rebuild-every-pull-1.txt","audits/evidence/p6/2a/p2/HOME/verify-home-full-rebuild-every-pull-2.json","audits/evidence/p6/2a/p2/HOME/leads-cost.json"]),
  K2("P2-HOME-06", "Kid Verse's feed lines no longer carry the kid's name (\"Read the verse ★\", \"Earned the … badge\", \"Heard this week's story\"); the TV and Home keep the name as the byline. verify2-tv-kid-name-doubled-1: TV lines repeating the name 3 → 0 (\"🦖 Ezra Ezra read the verse ★\" → \"🦖 Ezra Read the verse ★\"); -2: the same on the TV and the adult Home feed. rescale-1x only rescales the screenshot (same output).", ["audits/evidence/p6/2a/tests/repro-after/phase2__HOME__verify2-tv-kid-name-doubled-1.txt","audits/evidence/p6/2a/tests/repro-after/phase2__HOME__verify2-tv-kid-name-doubled-2.txt","audits/evidence/p6/2a/p2/HOME/verify2-tv-kid-name-doubled-1.json","audits/evidence/p6/2a/p2/HOME/verify2-tv-kid-name-doubled-1-home-feed.png"]),
  K2("P2-PROF-12", "The picker opens scrolled to the top with its title below the safe area. verify-picker-title-hidden-iphone-2 (empty, typical, overflow × four iPhone viewports × WebKit and Chromium): the title started above the top in 18 of 24 runs (h1 as far as −442 px) → 0 of 24, \"title fully in view\" with the h1 at 32 px (47 px where the panel fits). standalone: the picker title at −31 px → clear.", ["audits/evidence/p6/2a/tests/repro-after/phase2__PROF__verify-picker-title-hidden-iphone-2.txt","audits/evidence/p6/2a/p2/PROF/verify-picker-title-2.json","audits/evidence/p6/2a/p2/PROF/verify-picker-title-2-webkit-typical-iphone-pwa.png"]),
  K2("P2-PROF-18", "A guest's Me kicker reads \"Guest · until <date>\". verify-guest-hero-adult-2: a fresh guest \"Adult\" → \"Guest · until Sep 29\", Grandma Jo \"Adult\" → \"Guest · until Sep 28\"; the controls are unchanged (David \"Adult\", Eli \"Adult · Admin\"). The screens reviewer's nit is fixed: the date no longer splits across lines (Me hero composite).", ["audits/evidence/p6/2a/tests/repro-after/phase2__PROF__verify-guest-hero-adult-2.txt","audits/evidence/p6/2a/p2/PROF/verify-guest-hero-adult-2-seeded-grandmajo-iphone-pwa.png","audits/evidence/p6/2a/review/m-mehero.png"]),
  K2("P2-PWA-17", "The chat composer keeps to the side safe-area insets. verify2-chat-composer-under-sensor-landscape-1 (932×430 landscape): the form 26-906 → 75-857 px, in the 59 px sensor bands 33 px each side → clear; the mic and Send 24 px in the band → clear; covered area 330 → 0 px². standalone: composer, mic and Send \"clear\" (were over both bands).", ["audits/evidence/p6/2a/tests/repro-after/phase2__PWA__verify2-chat-composer-under-sensor-landscape-1.txt","audits/evidence/p6/2a/p2/PWA/verify2-chat-composer-under-sensor-landscape-1.json","audits/evidence/p6/2a/p2/PWA/standalone-safe-chat-landscape-iphone-pwa-light.png"]),
  K2("P2-SYNC-13", "Me's Sync card repaints on every sync change, like the tab-bar dot. verify-me-sync-card-stale-2: after the first pull and the 30 s pull the card said \"pending · Last checked not yet\" while the dot said synced → \"Up to date · Last synced 5:30 PM\"; 3 and 8 s after a theme pick it kept \"pending · 1 waiting\" → \"Up to date · nothing\"; after a Switch to Ezra likewise. The card now matches the dot at every step.", ["audits/evidence/p6/2a/tests/repro-after/phase2__SYNC__verify-me-sync-card-stale-2.txt","audits/evidence/p6/2a/p2/SYNC/verify-me-sync-card-stale-2.json","audits/evidence/p6/2a/p2/SYNC/e7-phone-me-sync-card-5s-after-theme.png"]),
  K2("P2-SYNC-14", "The last successful sync is kept per device (hub.lastSync in localStorage, hub.lastSynced()) and shown as \"Last synced <time>\". verify-last-checked-not-persisted-2: reopened offline, \"Last checked: not yet\" → \"Last synced 5:30 PM\"; localStorage now holds hub.lastSync. e7-sync-ui part 2 agrees (\"not yet\" → \"5:30 PM\").", ["audits/evidence/p6/2a/tests/repro-after/phase2__SYNC__verify-last-checked-not-persisted-2.txt","audits/evidence/p6/2a/p2/SYNC/verify-last-checked-not-persisted-2.json","audits/evidence/p6/2a/p2/SYNC/verify-lcnp-2-B-offline-reopen-sync-card.png"]),
  K2("P2-VIS-05", "Kid names truncate with an ellipsis and ★ and the badge count stay visible. verify-kids-chip-clipped-1 before: long names lost the badge count on all three devices and the ★ on the iPad. The filed after run crashes on the iPhone's short-name case (the Kids card is now an off-screen pager page, so its screenshot clip is 0 wide) before reaching the long names. The findings reviewer's copy patched to open that pager page passes typical, long and 40-character names on desktop, iPad and iPhone: ★ and badges visible in all 18 chips (filed under review/kids-chip/).", ["audits/evidence/p6/2a/review/kids-chip/verify-kids-chip-clipped-1-webkit.json","audits/evidence/p6/2a/review/kids-chip/verify-kids-chip-max40-iphone-pwa-webkit.png","audits/evidence/p6/2a/tests/repro-before/phase2__VIS__verify-kids-chip-clipped-1.txt","audits/evidence/p6/2a/tests/repro-after/phase2__VIS__verify-kids-chip-clipped-1.txt"]),
  K2("P4-MOTION-01", "The Apps grid re-renders only when the app list changes and never replays its entrance on a pull. MOTION/replay: hub-pop on Apps tiles 18 (at 28 and 58 s) → 0; Home and TV 0 → 0. MOTION/replay-shot timed tiles dimming 1 → 0 → 1 before; after it times out waiting for a tile to dim, because none does.", ["audits/evidence/p6/2a/tests/repro-after/phase4__MOTION__replay.txt","audits/evidence/p6/2a/p4/MOTION/replay.json","audits/evidence/p6/2a/tests/repro-after/phase4__MOTION__replay-shot.txt"]),
  K2("P4-MOTION-02", "The viewer's exit can be interrupted. MOTION/viewer: a tap on the Timer tile 80 ms into the exit hit the fading iframe and left the viewer closed on about:blank → it hits the tile and Timer opens; a hash change to #timer during the exit left it blank → Timer open. A normal close still plays viewer-out; the closed app now stays loaded hidden (UX-HOME-5).", ["audits/evidence/p6/2a/tests/repro-after/phase4__MOTION__viewer.txt","audits/evidence/p6/2a/p4/MOTION/viewer.json","audits/evidence/p6/2a/p4/MOTION/viewer-open-during-exit-ipad.png"]),
  K2("PWA-GAP-3", "Home's \"Add a reminder for the house\" has a mic (hub.voiceInput) between the field and +, and the placeholder is no longer cut by it (leads retype screenshot). The rig has no speech recognition, so dictation into the field was not tried. On the iPad, tap the mic beside Add a reminder, say \"buy milk\" and check that the words land in the field. The Kitchen device's reminder field has no mic (kitchen composites).", ["audits/evidence/p6/2a/p2/HOME/leads-retype-after.png","audits/evidence/p6/2a/p2/HOME/verify2-reminder-draft-end-webkit.png"], "NEEDS DEVICE CHECK"),
  K2("PWA-UX-4", "A kid's spoken question sends itself when speech ends (no Send tap). Nothing in the rig can speak into the mic, so this rests on the code and the reviewers' reading. On the iPad as Ezra, open Chat, tap the mic, say \"what is my verse\" and check that it sends by itself when you stop and that the answer is read aloud.", ["audits/evidence/p6/2a/tests/smoke-chat.txt"], "NEEDS DEVICE CHECK"),
  K2("UX-CHAT-02", "A failed send shows a plain-English error with Retry and puts the text back in the field; offline messages are queued (hub.chatq.<id>), survive a reload and send when the connection returns, on any tab, for the signed-in person only. The worker's probe (not filed): a 500 reads \"The assistant is busy right now. Your message is kept — tap Retry in a moment.\" with the text kept; offline \"Waiting for the connection — it sends by itself\", still there after a reload. The security review's offline-queue and double-send findings are fixed and confirmed. No filed screenshot.", ["audits/evidence/p6/2a/tests/smoke-chat.txt"]),
  K2("UX-CHAT-03", "Failed or refused writes show a red chip; the client renders tool events with ok:false (the Worker still sends chip null for them, e.g. smoke-chat's refused set_data: ok false, chip null). Confirmed by the findings reviewer; smoke-chat 53/0. No filed screenshot.", ["audits/evidence/p6/2a/tests/smoke-chat.txt"]),
  K2("UX-CHAT-04", "At the cap Send is disabled, the placeholder says \"Back tomorrow\" and \"60/60\" sits in the composer. The worker's probe (not filed): sendDisabled true, the counter visible, placeholder \"Back tomorrow\". Confirmed by the findings reviewer. No filed screenshot.", ["audits/evidence/p6/2a/tests/smoke-chat.txt"]),
  K2("UX-CHAT-05", "The Chat tab shows only the last 36 h, the window the model still has, under a divider \"Earlier messages are not remembered\". The worker's probe (not filed): an older message hidden, the divider shown. Confirmed by the findings reviewer. No filed screenshot.", ["audits/evidence/p6/2a/tests/smoke-chat.txt"]),
  K2("UX-CHAT-06", "Chips and feed lines use words, not storage keys: smoke-chat's set_data chip \"✓ Tally set to 42\"; set_data's feed line is worded in worker/src/chat.js; the client rewrites only a chip that still holds a key and keeps the Worker's worded chips (review nit 11). smoke-chat 53/0.", ["audits/evidence/p6/2a/tests/smoke-chat.txt"]),
  K2("UX-CHAT-07", "The chat log has day separators and a time under each bubble (history's created_at). The standalone landscape screenshot shows \"6:15 AM\" under both bubbles; the worker's probe (not filed) found the day separators and 12 times.", ["audits/evidence/p6/2a/p2/PWA/standalone-safe-chat-landscape-iphone-pwa-light.png"]),
  K2("UX-HOME-3", "On a phone Home is a short glance: a compact hero, the cards in a horizontal pager with dots, Reminders on the first screen (screens composite); on a park day the park card comes first (screens reviewer, confirmed). A capture cannot show how the pager moves under a finger. On an iPhone, flick the Home cards sideways: each flick should settle on one card with the dots following, and scrolling up and down over the cards should still scroll the page.", ["audits/evidence/p6/2a/review/m-s.png"], "NEEDS DEVICE CHECK"),
  K2("UX-HOME-4", "The viewer's back button returns to where the app was opened and names it (\"‹ Home\" from a Home card, \"‹ Apps\" from the grid); Escape closes the viewer. The worker's probe (not filed): Escape from the Larder lands on Home with the viewer closed.", ["audits/evidence/p6/2a/review/m-viewer.png","audits/evidence/p6/2a/p4/MOTION/viewer-open-during-exit-ipad.png"]),
  K2("UX-HOME-5", "A closed app stays loaded, hidden, for 60 s (Switch, sign-out and the timer drop it), so reopening the same app keeps what was typed: MOTION/viewer, the frame after a close apps/tally.html (was about:blank); the findings reviewer's probe (not filed): the Larder's \"Half-typed soup\" kept on reopening. App to app through the Switch sheet still reloads and loses it, and there is no hub.draft(). No batch is named for the rest.", ["audits/evidence/p6/2a/tests/repro-after/phase4__MOTION__viewer.txt","audits/evidence/p6/2a/p4/MOTION/viewer.json"], "PARTIAL"),
  K2("UX-HOME-6", "The Switch-app sheet is a grid of the apps' tile icons in their own colours (80 px for kids). The worker's probe (not filed): 8 of 8 entries with an icon and an app colour, 94-109 px tall (was 0 of 8). The screens reviewer made the sheet solid enough over busy pages. No filed screenshot of the sheet; the Apps grid composite shows the same tile icons and colours.", ["audits/evidence/p6/2a/review/m-s.png"]),
  K2("UX-HOME-7", "Kid Home is picture-first: big art tiles for Kid Verse, Prayer, Timer and Tally plus All my apps, stars drawn as stars with the count at 10.4 mm, no Reminders block. leads cold kid: the reminders card gone (skeletons 3 → 1); switch-lands-1: Ezra's Home cards \"Stars, Reminders\" → \"Stars\"; test-home kid checks pass.", ["audits/evidence/p6/2a/p2/HOME/glance-kid-ipad-portrait.png","audits/evidence/p6/2a/p2/HOME/leads-cold.json","audits/evidence/p6/2a/tests/suites/test-home.txt"]),
  K2("UX-PROF-a1", "The picker drops guests whose stay has ended, from the cached list too. The worker's probe offline (not filed): the expired guest not shown; test-guests: the picker hides an expired guest and she cannot sign in.", ["audits/evidence/p6/2a/tests/suites/test-guests.txt"]),
  K2("UX-PROF-a3", "Changed from the proposed fix, because signing in needs the server: offline, the picker says so before anyone taps (\"Offline — signing in needs the house connection…\"), disables the cards and offers Try again (automatic when back online), also when the connection drops while it is showing (review fix 17). The worker's probe (not filed): 8 of 8 cards disabled with the note. No filed screenshot; the capture rig's offline picker screens were changed to capture this state.", ["audits/evidence/p6/2a/tests/suites/test-hub.txt"]),
  K2("UX-PROF-a4", "The Create-PIN pad names the person with their face (\"Create Mea's PIN\") and puts focus on the pad. test-hub: adult without a PIN gets \"Create Mea's PIN\"; the worker's probe (not filed): focus on the first digit.", ["audits/evidence/p6/2a/tests/suites/test-hub.txt"]),
  K2("UX-PROF-a5", "On a lockout (429) the pad disables itself and counts down (\"Too many tries. Try again in 14 min.\"), using the retry time the SDK error now carries. The worker's probe (not filed): digits disabled with the countdown. smoke-api 275/0 keeps the server limits. No filed screenshot.", ["audits/evidence/p6/2a/tests/smoke-api.txt"]),
  K2("UX-PROF-a8", "The \"Choose a pairing code\" sheet has real labels and a Cancel button and closes on Escape; every shell sheet now closes by dragging it down. Cancel and the labels were confirmed by the findings reviewer; a drag cannot be proven in the rig. On an iPhone, open Me → Admin → Choose a new code, drag the sheet down by its handle and check it follows the finger and closes; then check Cancel.", ["audits/evidence/p6/2a/review/m-admin.png"], "NEEDS DEVICE CHECK"),
  K2("UX-PROF-a9", "Kid-mode shell controls reach 64 px with icons: the tab bar 56 → 64 px (switch-lands-1: Ezra's Home tab h 56 → 64), the viewer bar's back, name and reload 64 px with icons (worker's probe, not filed), Me's Switch 64 px; Notifications and Forget this device are hidden for kids. test-hub: kid tap targets ≥ 64 px.", ["audits/evidence/p6/2a/tests/repro-after/phase2__HOME__verify-switch-lands-on-me-1.txt","audits/evidence/p6/2a/tests/suites/test-hub.txt","audits/evidence/p6/2a/p2/HOME/glance-kid-ipad-portrait.png"]),
  K2("VIS-GLASS-2", "The app viewer's bar is solid material, since nothing passes beneath it: the worker's probe (not filed) reads background rgb(255,255,255) with no backdrop filter and no sheen layer. After screenshots: the viewer composite and the Timer opened during an exit.", ["audits/evidence/p6/2a/review/m-viewer.png","audits/evidence/p6/2a/p4/MOTION/viewer-open-during-exit-ipad.png"]),
  K2("VIS-HOME-1", "The Apps grid is sized per class: 60 px icons on a phone and 76 px from the iPad, in each app's own colour family, caption labels, 4 columns on a phone (screens composite). One nit is left: at text size XXL, \"Dollywood\" breaks mid-word in headless WebKit and Chromium, and whether Safari hyphenates it depends on the device. On an iPhone at text size XXL, open Apps and check that the two Dollywood labels break between words or at a hyphen.", ["audits/evidence/p6/2a/review/m-s.png"], "NEEDS DEVICE CHECK"),
  K2("VIS-HOME-2", "The timer pill keeps its own space: on phone and iPad the scroller ends above the pill's band, on landscape and desktop it sits at the sidebar's foot. leads pill, four devices: over reminder text, headings and cards at the top and at the end of the page → over nothing; clearance at the end −32 → +32/33 px on phone and iPad portrait.", ["audits/evidence/p6/2a/p2/HOME/leads-pill.json","audits/evidence/p6/2a/p2/HOME/leads-pill-ipad-portrait-bottom.png","audits/evidence/p6/2a/p2/HOME/leads-pill-ipad-landscape-top.png","audits/evidence/p6/2a/tests/repro-after/phase2__HOME__leads.txt"]),
  K2("VIS-HOME-3", "At 1024 px and wider Home is a 6-column grid with spans: the Kids card spans the row instead of sitting alone beside empty cells, the hero summary has no 34ch cap and chips truncate with an ellipsis (\"read today ✓ · 26…\"). After screenshots at 1180 and 820.", ["audits/evidence/p6/2a/p2/HOME/glance-timer-ipad-landscape.png","audits/evidence/p6/2a/p2/HOME/glance-adult-ipad-portrait.png"]),
  K2("VIS-TIMER-5", "The chat log keeps room for the timer pill above the composer: the landscape chat screenshot shows the pill between the newest bubble and the composer, touching neither. test-timer 45/0: on Chat at 390 and 820 the pill sits 12 px above the composer and at 1440 in the sidebar, the input, mic and Send uncovered.", ["audits/evidence/p6/2a/p2/PWA/standalone-safe-chat-landscape-iphone-pwa-light.png","audits/evidence/p6/2a/tests/suites/test-timer.txt"]),
  K2("CONS-TOK-4", "The shell's icon corners are calc(var(--icon-box) * var(--r-icon-ratio)) (0.225, D9): a size sets only --icon-box (index.html:200 and on; apps/design.css:1155), and the one literal radius left in index.html is the theme swatch (6 px). After screenshots: the Apps grid and kid Home icons.", ["audits/evidence/p6/2a/review/m-s.png","audits/evidence/p6/2a/p2/HOME/glance-kid-ipad-portrait.png"]),
  K2("P2-STAB-06", "Pointer to P2-PWA-05: the feed reloads on every pull and when the page becomes visible (verify-feed-not-live-1: Mom's line false → true from the 30 s pull).", ["audits/evidence/p6/2a/tests/repro-after/phase2__PWA__verify-feed-not-live-1.txt"]),
  K2("P2-SYNC-10", "Pointer to P2-PWA-05: the feed refreshes on its own with each pull (verify-feed-not-live-1: 0 → 2 feed requests in 70 s, Mom's line shown).", ["audits/evidence/p6/2a/tests/repro-after/phase2__PWA__verify-feed-not-live-1.txt"]),
  K2("P2-VIS-07", "Pointer to P2-SYNC-13: Me repaints on sync and change, and Kids' rewards and the album show loading placeholders until their data arrives, so no final empty state or ★0 paints on a cold load (verify-me-sync-card-stale-2: the card updates after the first pull without re-entering Me).", ["audits/evidence/p6/2a/tests/repro-after/phase2__SYNC__verify-me-sync-card-stale-2.txt"]),
  K2("PWA-UX-3", "Pointer to PWA-UX-4 and P2-PWA-17. The composer's safe-area half (P2-PWA-17) is FIXED; the kid's spoken question sending itself (PWA-UX-4) awaits the iPad check named there.", ["audits/evidence/p6/2a/tests/repro-after/phase2__PWA__verify2-chat-composer-under-sensor-landscape-1.txt"], "NEEDS DEVICE CHECK"),
  K2("PWA-VIS-1", "Pointer to P2-HOME-06, adult-Home facet included: verify2-tv-kid-name-doubled-2's adult Home feed \"Ezra | Ezra heard this week's story …\" → \"Ezra | Heard this week's story …\".", ["audits/evidence/p6/2a/tests/repro-after/phase2__HOME__verify2-tv-kid-name-doubled-2.txt","audits/evidence/p6/2a/p2/HOME/verify2-tv-kid-name-doubled-1-home-feed.png"]),
  K2("PWA-VIS-2", "Pointer to P2-PWA-17: the composer keeps to the side insets in landscape (form 26-906 → 75-857 px at 932×430, mic and Send clear).", ["audits/evidence/p6/2a/tests/repro-after/phase2__PWA__verify2-chat-composer-under-sensor-landscape-1.txt"]),
  K2("PWA-VIS-3", "Pointer to P2-PROF-12: the picker opens at the top with its title in view (18 of 24 runs off the top → 0).", ["audits/evidence/p6/2a/tests/repro-after/phase2__PROF__verify-picker-title-hidden-iphone-2.txt"]),
  K2("UX-DOLLYWOOD-6", "Pointer to UX-SYNC-a1: the viewer bar shows \"Offline · 1 waiting\" over the park map while a change is unsent (viewer composite).", ["audits/evidence/p6/2a/review/m-viewer.png"]),
  K2("UX-KIDVERSE-7", "Pointer to UX-SYNC-a1: the shared pending state (\"Saving…\" / \"Offline · N waiting\") shows in the viewer bar over every app, Kid Verse included.", ["audits/evidence/p6/2a/review/m-viewer.png"]),
  K2("UX-LEFTOVERS-7", "Pointer to UX-SYNC-a1: the viewer bar shows \"1 waiting\" over the Larder while its change is unsent (viewer composite).", ["audits/evidence/p6/2a/review/m-viewer.png"]),
  K2("UX-TIMER-8", "Pointer to UX-SYNC-a1: the viewer bar shows the pending state over the Timer too, so a timer started offline says it has not reached the other devices yet.", ["audits/evidence/p6/2a/review/m-viewer.png"]),
];

// Batch 2b (the Worker: push, reminders, chat and the PWA): after-evidence under audits/evidence/p6/2b/ (the finding
// scripts' outputs in p2/ p3/, every script's console output before and after in tests/ incl. the patched copies filed in
// audits/tools/phase6/2b/, the checks in checks/, the reviewers' before/after repros in review/).
const W2 = (id, note, after, status = 'FIXED') => [id, { status, batch: '2b', note, after }];
const S2b = [
  W2("P2-PWA-02", "parkJob now runs at every firing of a new every-15-minutes cron; a kid is quiet after 20 min without an update, timed by the house's clock, and each quiet spell is told once per adult. The original verify-park-alert-misses-park-day-2 fails before and after: since batch 0d a kid's dot is refused (beacon_off). The patched copy switches Ezra's beacon on and runs the real scheduled handler in process. Every 15 min: 15/15 quiet spells alerted, 25-35 min after they began (pre-batch 7/15: tests/repro-before/park-kidshare-before-every15.txt). At the old 8/9 o'clock instants: 15/15 (pre-batch 5/15, and a guest was pushed: park-kidshare-before.txt). test-park 20/0, cron-check 18/18. The copy's Part B no longer tests anything: every dot reads 0 min old by the house's clock.", ["audits/evidence/p6/2b/tests/repro-after/p6-2b__verify-park-kidshare-every15.txt","audits/evidence/p6/2b/p2/PWA/verify-park-alert-misses-park-day-2-kidshare-every15.json","audits/evidence/p6/2b/tests/suites/test-park.txt","audits/evidence/p6/2b/tests/repro-after/p6-2b__cron-check.txt"]),
  W2("P2-CHAT-05", "The Worker gives up after 45 s of upstream silence (upstream_timeout) and refunds the message. The Chat tab has a Stop button in Send's place; on Stop the Worker aborts and runs no tool after it. verify-no-timeout-on-hang-2 (WebKit, 150 s hang): before, it released at 67 s with a false \"No connection\" and the message spent (4 → 5); after, it releases at 46 s with \"The assistant is busy right now… tap Retry\", and used is back to 4. check-2b 16/16: Stop takes Send's place (≥ 44 px) and gives the message back. Review stop-write: a Stop let the soup still be added (1 row, used 4 → 5) → 0 rows, 4 → 4. Only the mock was used, not the real Anthropic API.", ["audits/evidence/p6/2b/tests/repro-after/phase2__CHAT__verify-no-timeout-on-hang-2.txt","audits/evidence/p6/2b/p2/CHAT/verify-no-timeout-on-hang-2-webkit.json","audits/evidence/p6/2b/tests/repro-after/p6-2b__check-2b.txt","audits/evidence/p6/2b/review/after-rev/stop-write.txt"]),
  W2("P2-PWA-03", "Switch deletes that person's subscription on the device, and every sign-in deletes other people's rows there. A PIN reset deletes the person's rows; Me shows the switch for whoever is signed in. verify-shared-device-push-follows-device-2 stops at 4b by design: Mom's switch now reads Off, so the test button it taps is hidden. Its patched copy: after Eli's Switch, server rows 1 → 0, and the admin's test and the 8 pm F260 nudge no longer reach the iPad (1 → 0 each); Mom sees \"Off for you on this device\" (was On). push.mjs: Eli's rows after Switch 2 → 1, and a push to him reaches only his phone. Review probe B: Mom's reminder to pray reached the iPad after her PIN reset → nothing.", ["audits/evidence/p6/2b/tests/repro-after/p6-2b__verify-shared-device-b2b.txt","audits/evidence/p6/2b/p2/PWA/verify-shared-device-push-follows-device-2-b2b.json","audits/evidence/p6/2b/tests/repro-after/phase2__PWA__push.txt","audits/evidence/p6/2b/review/after-rev/probes.txt"]),
  W2("P2-PWA-04", "Each adult is owed each new family request until a push to them is delivered, and prayer pushes no longer have a once-a-day gate. verify-prayer-push-lost-after-morning-1, scenario A: a prayer was pushed at 8 am and Dad added another at 12:30. Before, the second one reached only Mom; after, it reaches Eli, Mae, Mom and Mea at 8 pm, the same as control B. The guest no longer gets either one (PWA-UX-2, by design). test-push2 61/0: a second new prayer the same day still reaches Mae.", ["audits/evidence/p6/2b/tests/repro-after/phase2__PWA__verify-prayer-push-lost-after-morning-1.txt","audits/evidence/p6/2b/tests/repro-before/phase2__PWA__verify-prayer-push-lost-after-morning-1.txt","audits/evidence/p6/2b/p2/PWA/verify-prayer-push-lost-after-morning-1.json","audits/evidence/p6/2b/tests/suites/test-push2.txt"]),
  W2("P2-PWA-08", "An open hub checks for a new build when it becomes visible and every hour. It reloads the same tab when hidden, or after 20 s idle with no app or sheet in use, nothing typed and no chat reply on its way. verify-open-page-never-takes-new-build-2: after the new service worker took over, the iPad and the TV kept running ORIGINAL under a false \"next time it opens\" toast → both run NEW-DEPLOY on the same hash. Review swprobe: a half-typed Larder entry was lost to the reload → kept; swprobe3: six untouched apps reload. The script forces the TV's update check, so the hourly timer itself was not waited for.", ["audits/evidence/p6/2b/tests/repro-after/phase2__PWA__verify-open-page-never-takes-new-build-2.txt","audits/evidence/p6/2b/p2/PWA/verify-open-page-never-takes-new-build-2.json","audits/evidence/p6/2b/review/after-rev/swprobe.txt","audits/evidence/p6/2b/review/after-rev/swprobe3.txt"]),
  W2("P2-PWA-09", "sw.js precaches with cache:'reload' and revalidates with no-cache, so a VERSION bump stores the deployed files. verify-deploy-invisible-within-max-age-2 now stops with \"fix patch did not apply\": it tries to patch in this same fix, which is already there. Its patched copy, on a stand-in server at max-age=600 and 15: before, run A cached the OLD ./, index.html and hub.js, and all three cold opens ran ORIGINAL (B: one). After, A, B and C cache the DEPLOYED files and every cold open runs DEPLOYED-BUILD-2. The copy's \"activated\" flag reads false only because the new hub-config cache makes two caches. The open page's toast now says \"The hub is up to date.\"", ["audits/evidence/p6/2b/tests/repro-after/p6-2b__verify-deploy-b2b.txt","audits/evidence/p6/2b/p2/PWA/verify-deploy-invisible-within-max-age-2-b2b.json","audits/evidence/p6/2b/tests/repro-before/phase2__PWA__verify-deploy-invisible-within-max-age-2.txt","audits/evidence/p6/2b/tests/repro-after/phase2__PWA__verify-deploy-invisible-within-max-age-2.txt"]),
  W2("GAP-CHAT-01", "Me → Chat history → Clear my chat history (DELETE /api/chat/history, behind the confirm sheet) empties a person's history; today's count stays. Kids' chat is deleted after 90 days by the scheduled run. check-2b: Clear empties the history, and a kid gets the Chat history card but the TV does not. cron-check: the 8 pm firing deletes a kid's 90-day-old chat but not an adult's. smoke-api: clear my chat history returns 200. Review chatprobe: 20 rows deleted, the day's count kept at 10.", ["audits/evidence/p6/2b/check-2b/me-chat-hist-eli-webkit.png","audits/evidence/p6/2b/tests/repro-after/p6-2b__check-2b.txt","audits/evidence/p6/2b/tests/repro-after/p6-2b__cron-check.txt","audits/evidence/p6/2b/tests/smoke-api.txt"]),
  W2("P2-CHAT-08", "The daily cap is now taken in one step through a counter row. verify-cap-check-not-atomic-1, Worker arms at every latency: before, 2 sends at 59/60 went 1 over and 10 sends at 57/60 went 7 over; after, 0 over (the rest get 429). A burst of 100 at 59 reached 159 → 60 (1 × 200, 99 × 429, one upstream call). Ten sends 5 ms apart went 69 → 60.", ["audits/evidence/p6/2b/tests/repro-after/phase2__CHAT__verify-cap-check-not-atomic-1.txt","audits/evidence/p6/2b/tests/repro-before/phase2__CHAT__verify-cap-check-not-atomic-1.txt","audits/evidence/p6/2b/p2/CHAT/verify-cap-check-not-atomic-1.json"]),
  W2("P2-CHAT-10", "A message is refunded when the upstream fails or times out before any reply, and the error event says so (refunded). verify-failed-upstream-spends-cap-1: a 500, a 429 and a stream error each cost a message (1 → 4) → used stays 1. An outage hit the cap after 59 failed retries → 80 failures, used still 1, no cap. The success control still counts (1 → 2). Review round 2: a Stop after the model was asked counts one message; only an upstream failure or timeout refunds.", ["audits/evidence/p6/2b/tests/repro-after/phase2__CHAT__verify-failed-upstream-spends-cap-1.txt","audits/evidence/p6/2b/tests/repro-before/phase2__CHAT__verify-failed-upstream-spends-cap-1.txt","audits/evidence/p6/2b/p2/CHAT/verify-failed-upstream-spends-cap-1.json"]),
  W2("P2-CHAT-11", "The tool loop replays thinking and redacted_thinking blocks whole, first in the assistant turn. verify-thinking-blocks-dropped-on-tool-replay-1, thinking blocks in the replayed body: write + replay 0 → 1; interleaved 0 → 1 (second call) and 0 → 2 (third); redacted 0 → 1. In all three, the last assistant turn now starts with a thinking block. Checked against the mock, not the real API.", ["audits/evidence/p6/2b/tests/repro-after/phase2__CHAT__verify-thinking-blocks-dropped-on-tool-replay-1.txt","audits/evidence/p6/2b/tests/repro-before/phase2__CHAT__verify-thinking-blocks-dropped-on-tool-replay-1.txt","audits/evidence/p6/2b/p2/CHAT/verify-thinking-blocks-dropped-on-tool-replay-1.json"]),
  W2("P2-CHAT-12", "The system prompt marks the signed-in admin and each guest, and leaves out expired guests and the TV. verify-prompt-admin-and-expired-guests-1: \"Signed in now: Eli (adult)\" → \"Eli (adult, admin)\". Expired guests in the prompts: Visitor Vic (Mae's and Ezra's) and Cousin Theo true → false; the kiosk also true → false. Live guests now read \"(adult, guest)\".", ["audits/evidence/p6/2b/tests/repro-after/phase2__CHAT__verify-prompt-admin-and-expired-guests-1.txt","audits/evidence/p6/2b/tests/repro-before/phase2__CHAT__verify-prompt-admin-and-expired-guests-1.txt","audits/evidence/p6/2b/p2/CHAT/verify-prompt-admin-and-expired-guests-1.json"]),
  W2("P2-CHAT-13", "Admin → Usage groups chat and push by New York day and says so. verify-usage-utc-vs-cap-1: Dad's four messages were grouped by UTC day (23rd: 1, 22nd: 3) → 22nd: 2, 21st: 2, the same days the cap uses; the admin table matches. Eli: 22nd: 5 → 22nd: 4, 21st: 1. check-2b: the panel says the days are New York days.", ["audits/evidence/p6/2b/tests/repro-after/phase2__CHAT__verify-usage-utc-vs-cap-1.txt","audits/evidence/p6/2b/p2/CHAT/verify-usage-utc-vs-cap-1.json","audits/evidence/p6/2b/p2/CHAT/verify-usage-utc-vs-cap-1-admin.png","audits/evidence/p6/2b/tests/repro-after/p6-2b__check-2b.txt"]),
  W2("P2-PROF-16", "The Worker refuses push subscribe and test for the TV (403 read_only) and for kids and the Kitchen device (403 no_push); their Me shows no Notifications card. verify-kiosk-push-allowed-2: the TV's subscribe and test went 200/200 with one push delivered → 403/403, nothing received. Ezra's went 200/200 → 403/403. Subscriptions left after the run: TV 1 and Ezra 1 → none. push.mjs: Ezra, Kiara and the TV subscribe 200 → 403. smoke-api: a kid and the kitchen are refused. check-2b: a kid and the TV get no Notifications card.", ["audits/evidence/p6/2b/tests/repro-after/phase2__PROF__verify-kiosk-push-allowed-2.txt","audits/evidence/p6/2b/tests/repro-before/phase2__PROF__verify-kiosk-push-allowed-2.txt","audits/evidence/p6/2b/p2/PROF/verify-kiosk-push-allowed-2.json","audits/evidence/p6/2b/tests/repro-after/p6-2b__check-2b.txt"]),
  W2("P2-PWA-10", "Subscribe needs an endpoint and both keys (400 bad_subscription). pushTo deletes a row it cannot encrypt for and carries on. verify-keyless-subscription-aborts-job-1: Mae's keyless subscribe 200 → 400. The 8 am job, on two mornings, and the 8 pm prayer job returned 500 (TypeError, only Eli told) → 200 with the adults told. On the real scheduled handler with a keyless row put in directly: the morning job's error → the other adults told and the bad row deleted. A kid's keyless subscribe 200 → 403.", ["audits/evidence/p6/2b/tests/repro-after/phase2__PWA__verify-keyless-subscription-aborts-job-1.txt","audits/evidence/p6/2b/tests/repro-before/phase2__PWA__verify-keyless-subscription-aborts-job-1.txt","audits/evidence/p6/2b/p2/PWA/verify-keyless-subscription-aborts-job-1.json"]),
  W2("P2-PWA-11", "Only a delivered push counts toward the daily gate. verify-failed-send-blocks-day-1: Mea's push service answered 503 at 8:00, and the 8:30 retry skipped her as already_today → she gets it at 8:30; Dad, who got his at 8:00, is still skipped. The script's park half shows nothing before or after, because no kid goes quiet in its set-up. Review dst: jobs are now eligible at each 15-min firing of the 8 am and 8 pm hours (1 → 4 firings), so a failed push is retried; cron-check: once delivered, nothing is sent twice.", ["audits/evidence/p6/2b/tests/repro-after/phase2__PWA__verify-failed-send-blocks-day-1.txt","audits/evidence/p6/2b/tests/repro-before/phase2__PWA__verify-failed-send-blocks-day-1.txt","audits/evidence/p6/2b/p2/PWA/verify-failed-send-blocks-day-1.json","audits/evidence/p6/2b/review/after-rev/dst.txt"]),
  W2("P2-PWA-12", "The test push goes only to this device's own subscription (the client sends its endpoint), and the toast says \"Sent to this device\". verify-test-button-counts-all-devices-2 now times out at A3 by design: Mom's switch reads Off on the iPad, so the button it taps is hidden. Its patched copy: Mom's raw test from the iPad sent to her phone (\"Sent\") → sent 0. Eli's test from the iPad reached his phone → reaches the Kitchen iPad only. push.mjs: a test with no row for this device sent 1 → 0 (\"No subscription on the server for this device yet\").", ["audits/evidence/p6/2b/tests/repro-after/p6-2b__verify-test-button-b2b.txt","audits/evidence/p6/2b/p2/PWA/verify-test-button-counts-all-devices-2-b2b.json","audits/evidence/p6/2b/p2/PWA/verify-test-button-counts-all-devices-2-b2b-A.png","audits/evidence/p6/2b/tests/repro-after/phase2__PWA__verify-test-button-counts-all-devices-2.txt"]),
  W2("P2-PWA-15", "\"Hub updated\" shows only when the page already had a controller before this load. verify-first-visit-hub-updated-2: first-install toasts 5/24 → 0/24 (WebKit bare 5/8 → 0/8). The new worker still claims the page before installed fires (in 9 runs, was 5), but the toast no longer follows.", ["audits/evidence/p6/2b/tests/repro-after/phase2__PWA__verify-first-visit-hub-updated-2.txt","audits/evidence/p6/2b/tests/repro-before/phase2__PWA__verify-first-visit-hub-updated-2.txt","audits/evidence/p6/2b/p2/PWA/verify-first-visit-hub-updated-2.json"]),
  W2("P2-PWA-16", "sw.js serves a styled offline.html (the hub's tokens and a ≥ 44 px Try again) for a page it has no copy of. verify-build-guide-offline-blank-1, build guide never opened: plain-text \"Offline\" in 13 px monospace → \"Not saved on this device yet … Open it once …\" in the theme, light and dark. After a VERSION bump it shows the same page; the copy is still dropped at each bump. The script's WebKit arm D replays the old response itself, so it still shows \"Offline\". check-2b: offline.html paints in four palettes with no sideways scroll.", ["audits/evidence/p6/2b/tests/repro-after/phase2__PWA__verify-build-guide-offline-blank-1.txt","audits/evidence/p6/2b/p2/PWA/verify-build-guide-offline-blank-1.json","audits/evidence/p6/2b/check-2b/offline-hearth-webkit.png","audits/evidence/p6/2b/check-2b/offline-midnight-webkit.png"]),
  W2("P3-PRAYER-25", "The prayer push identifies a family row by its id and createdAt, not its title. critic-push-share, after a title edit: announced as new → new []. verify-critic-title-edit-announced-as-new-9-1: Dad's title edit showed as new → new []. -9-2: before, pushed to Mae, Mom, Dad, Mea and the guest → nobody. A new request shared to the list is still announced (critic job3). test-push2: editing an existing prayer does not re-announce it.", ["audits/evidence/p6/2b/tests/repro-after/phase3__prayer__verify-critic-title-edit-announced-as-new-9-2.txt","audits/evidence/p6/2b/tests/repro-after/phase3__prayer__verify-critic-title-edit-announced-as-new-9-1.txt","audits/evidence/p6/2b/tests/repro-after/phase3__prayer__critic-push-share.txt","audits/evidence/p6/2b/p3/prayer/verify-critic-title-edit-announced-as-new-9-2.json"]),
  W2("PWA-GAP-2", "sw.js handles pushsubscriptionchange by posting the browser's new subscription to POST /api/push/resubscribe; the device token is required and only that device's row moves. The shell then re-syncs. smoke-api 315/0: resubscribe without a device token 401, from another device 404, by the old endpoint 200 (moved 1). Review probe A: an unauthenticated resubscribe that redirected Mom's pushes, 200 → 401, nothing received. The rig cannot make a browser rotate a subscription, so the event itself never fired. After the deploy, watch one iPhone Home Screen app: its 8 am and 8 pm pushes should keep arriving for weeks, and Admin → Usage should show no failed sends for it.", ["audits/evidence/p6/2b/tests/smoke-api.txt","audits/evidence/p6/2b/review/after-rev/probes.txt","audits/evidence/p6/2b/review/before-rev/probes.txt"], "NEEDS DEVICE CHECK"),
  W2("PWA-GAP-4", "manifest.json gains id, lang, dir, display_override, categories, four shortcuts (Prayer, Larder, F260, Chat) and a monochrome icon; the maskable icon was already there. The apple-touch-icon is now opaque (RGB, 180 px), and a 96 px badge icon was added for notifications. The review's renders of the monochrome and badge icons on blue show clean silhouettes. bump-sw: all 74 precached files present. Screenshots were not added. How Android draws the monochrome icon was not seen; the hub's devices are iPhone, iPad and desktop.", ["audits/evidence/p6/2b/review/icon-monochrome-on-blue.png","audits/evidence/p6/2b/review/badge-96-on-blue.png","audits/evidence/p6/2b/tests/bump-sw.txt"]),
  W2("PWA-UX-2", "Household pushes (fridge, new family prayers, park) skip guests, and a guest's Me hides those switches. Guests still get the weekly catch-up they can see. push.mjs: the guest's 8 am Larder push and the family prayer push are gone. verify-prayer-push-lost-after-morning-1 and verify-keyless-subscription-aborts-job-1: Grandma Jo is no longer told. check-2b: a guest has no household switches.", ["audits/evidence/p6/2b/tests/repro-after/phase2__PWA__push.txt","audits/evidence/p6/2b/tests/repro-before/phase2__PWA__push.txt","audits/evidence/p6/2b/tests/repro-after/p6-2b__check-2b.txt"]),
  W2("GAP-PRAYER-1", "Two new push kinds. praytime: a time chosen in Me (Off or one of 36 times), checked every 15 min, sent once a day, with no private titles on the lock screen. prayedfor: at 8 pm the person who asked hears \"X prayed for your request today\", once a day, and never about their own ticks. cron-check 18/18: Eli is reminded at his 8 pm slot, once; Mom hears that Eli and Ezra prayed, the receiver got both, and nothing is sent twice that day. check-2b: Eli's Me offers the time. Review prefs-stale: a tap on another switch no longer wipes the chosen time (08:30 kept).", ["audits/evidence/p6/2b/tests/repro-after/p6-2b__cron-check.txt","audits/evidence/p6/2b/tests/repro-after/p6-2b__check-2b.txt","audits/evidence/p6/2b/check-2b/me-notif-eli-webkit.png","audits/evidence/p6/2b/review/after-rev/prefs-stale.txt"]),
  W2("P2-STAB-05", "Pointer to P2-PWA-09: sw.js precaches with cache:'reload' and revalidates with no-cache. verify-deploy-b2b at max-age=600: cached files OLD → DEPLOYED, cold opens ORIGINAL ×3 → DEPLOYED-BUILD-2 ×3. The toast \"Hub updated — it will use the new version next time it opens\" → \"The hub is up to date.\", and the open page reloads to the new build (P2-PWA-08).", ["audits/evidence/p6/2b/tests/repro-after/p6-2b__verify-deploy-b2b.txt","audits/evidence/p6/2b/tests/repro-before/phase2__PWA__verify-deploy-invisible-within-max-age-2.txt"]),
  W2("P2-PROF-17", "Pointer to P2-CHAT-13: Admin → Usage groups by New York day (Dad: 23rd: 1, 22nd: 3 → 22nd: 2, 21st: 2) and says so.", ["audits/evidence/p6/2b/tests/repro-after/phase2__CHAT__verify-usage-utc-vs-cap-1.txt","audits/evidence/p6/2b/p2/CHAT/verify-usage-utc-vs-cap-1-admin.png"]),
  W2("P2-STAB-10", "Pointer to P2-PWA-15: a first install in WebKit no longer shows an update toast (5/24 → 0/24).", ["audits/evidence/p6/2b/tests/repro-after/phase2__PWA__verify-first-visit-hub-updated-2.txt"]),
  W2("PWA-UX-1", "Pointer to P2-PROF-16: kids and the TV are refused push (Ezra's subscribe and test 200/200 → 403/403). A kid's Me now has no Notifications card (check-2b, test-push2). An adult's card says \"On for you on this device. Choose what you get below.\" and lists one switch per kind they get (review me-notif).", ["audits/evidence/p6/2b/tests/repro-after/phase2__PROF__verify-kiosk-push-allowed-2.txt","audits/evidence/p6/2b/tests/repro-after/p6-2b__check-2b.txt","audits/evidence/p6/2b/review/after-rev/me-notif.txt"]),
];

